import collections
import json
import os
def task_func(directory_path: str) -> dict:
    def count_keys_in_json(file_path):
        """Recursively count keys in a JSON file."""
        with open(file_path, 'r', encoding='utf-8') as file:
            data = json.load(file)
        return count_keys(data)

    def count_keys(data):
        """Recursively count keys in a JSON object or list."""
        if isinstance(data, dict):
            counter = collections.Counter(data.keys())
            for value in data.values():
                counter.update(count_keys(value))
            return counter
        elif isinstance(data, list):
            counter = collections.Counter()
            for item in data:
                counter.update(count_keys(item))
            return counter
        else:
            return collections.Counter()

    key_counter = collections.Counter()

    # Traverse the directory and its subdirectories
    for root, _, files in os.walk(directory_path):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                key_counter.update(count_keys_in_json(file_path))

    return dict(key_counter)

