import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    # Check if the file exists
    if not os.path.exists(file_path):
        raise ValueError("File does not exist.")

    # Load the JSON data from the file
    try:
        with open(file_path, 'r') as file:
            data = json.load(file)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON format.")

    # Validate the JSON structure against the schema
    def validate_json(data, schema):
        if schema["type"] != "object":
            raise ValueError("Schema type must be 'object'.")

        for key, value in schema["properties"].items():
            if key not in data:
                if key in schema["required"]:
                    raise ValueError(f"Missing required attribute: {key}")
            else:
                if not isinstance(data[key], value["type"]):
                    raise ValueError(f"Type mismatch for attribute '{key}'. Expected {value['type'].__name__}, got {type(data[key]).__name__}.")

        # Validate email format
        if "email" in data and not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError("Invalid email format.")

    validate_json(data, INPUT_JSON)

    # Retrieve the specified attribute
    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON data.")

    return data[attribute]

