import re
import urllib.request
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(API_URL):
    try:
        # Make a request to the API URL
        with urllib.request.urlopen(API_URL) as response:
            # Read the response
            data = response.read().decode('utf-8')

            # Try to parse JSON if the response is in JSON format
            try:
                json_data = json.loads(data)
                # Check if the JSON contains a key that might have the IP address
                if 'ip' in json_data:
                    ip_address = json_data['ip']
                else:
                    # If not, use regex to find the IP address in the response
                    match = re.search(IP_REGEX, data)
                    if match:
                        ip_address = match.group(0)
                    else:
                        raise ValueError("IP address not found in the response.")
            except json.JSONDecodeError:
                # If the response is not JSON, use regex to find the IP address
                match = re.search(IP_REGEX, data)
                if match:
                    ip_address = match.group(0)
                else:
                    raise ValueError("IP address not found in the response.")

        # Validate the IP address format
        if not re.match(IP_REGEX, ip_address):
            raise ValueError("Invalid IP address format.")

        return ip_address

    except urllib.error.URLError as e:
        raise Exception(f"API request failed: {e.reason}")
    except urllib.error.HTTPError as e:
        raise Exception(f"HTTP error occurred: {e.code} - {e.reason}")
    except Exception as e:
        raise Exception(f"An error occurred: {str(e)}")

