import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    # Load JSON string into a Python dictionary
    data = json.loads(json_str)

    # Helper function to remove None values recursively
    def remove_none(obj):
        if isinstance(obj, dict):
            return {k: remove_none(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [remove_none(item) for item in obj if item is not None]
        else:
            return obj

    # Remove None values
    cleaned_data = remove_none(data)

    # Helper function to replace email addresses with REPLACE_NONE
    def replace_emails(obj):
        if isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_emails(item) for item in obj]
        elif isinstance(obj, str):
            return re.sub(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', REPLACE_NONE, obj)
        else:
            return obj

    # Replace email addresses
    processed_data = replace_emails(cleaned_data)

    # Flatten the data to count frequencies
    def flatten(obj, parent_key='', sep='_'):
        items = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                items.update(flatten(v, new_key, sep=sep))
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                new_key = f"{parent_key}{sep}{i}"
                items.update(flatten(v, new_key, sep=sep))
        else:
            items[parent_key] = obj
        return items

    # Flatten the processed data
    flattened_data = flatten(processed_data)

    # Count the frequency of each unique value
    value_counts = Counter(flattened_data.values())

    # Return the result as a dictionary
    return {
        "data": processed_data,
        "value_counts": value_counts
    }

